// The saved state is deliberately plain JSON so it can be inspected or reset by the player.
const SAVE_KEY='violet-veil-save-v1';
const PRESTIGE_THRESHOLD=1_000_000;
const OFFLINE_CAP=8*60*60*1000;
const initialState=()=>({essence:0,runEarned:0,totalEarned:0,sparks:0,levels:upgrades.map(()=>0),lastSaved:Date.now(),sound:false});
let state=initialState(),saveTimer=0,toastTimer=0,audioContext=null;
const $=id=>document.getElementById(id);
const numberFormat=value=>{
 if(!Number.isFinite(value))return '∞';
 const abs=Math.abs(value);
 if(abs<1000)return (abs%1===0?String(abs):abs.toFixed(abs<10?1:0)).replace(/\.0$/,'');
 const units=['K','M','B','T','Qa','Qi','Sx','Sp','Oc','No','Dc'];
 let tier=Math.floor(Math.log10(abs)/3);
 if(tier>units.length)return value.toExponential(2);
 const scaled=abs/Math.pow(1000,tier);
 return `${value<0?'-':''}${scaled.toFixed(scaled<10?1:0).replace(/\.0$/,'')}${units[tier-1]}`;
};
const multiplier=()=>1+state.sparks*.05;
const clickPower=()=>multiplier()*(1+upgrades.reduce((sum,u,i)=>sum+(u.kind==='click'?u.power*state.levels[i]:0),0));
const essencePerSecond=()=>multiplier()*upgrades.reduce((sum,u,i)=>sum+(u.kind==='eps'?u.power*state.levels[i]:0),0);
const upgradeCost=i=>Math.ceil(upgrades[i].base*Math.pow(1.2,state.levels[i]));
function showToast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function saveGame(){
 state.lastSaved=Date.now();
 try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('saveStatus').textContent='All progress saved';}
 catch(error){$('saveStatus').textContent='Save unavailable';console.warn('Could not save game:',error)}
}
function loadGame(){
 try{
  const saved=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');
  if(!saved||!Array.isArray(saved.levels))return;
  state={...initialState(),...saved};
  state.levels=upgrades.map((_,i)=>Math.max(0,Math.floor(Number(saved.levels[i])||0)));
  for(const key of ['essence','runEarned','totalEarned','sparks'])state[key]=Math.max(0,Number(saved[key])||0);
  state.sound=Boolean(saved.sound);
  const elapsed=Math.max(0,Math.min(OFFLINE_CAP,Date.now()-(Number(saved.lastSaved)||Date.now())));
  const away=essencePerSecond()*elapsed/1000;
  if(away>0){state.essence+=away;state.runEarned+=away;state.totalEarned+=away;state.offlineGain=away;}
 }catch(error){console.warn('Could not load save; starting a new age.',error);state=initialState()}
}
function renderShop(){
 const list=$('shopList');
 list.innerHTML=upgrades.map((u,i)=>{
  const level=state.levels[i],cost=upgradeCost(i),affordable=state.essence>=cost;
  const effect=u.kind==='click'?`+${numberFormat(u.power)} Essence / click`:`+${numberFormat(u.power)} Essence / second`;
  return `<button class="upgrade${affordable?' affordable':''}" data-upgrade="${i}" ${affordable?'':'disabled'} aria-label="Buy ${u.name}, costs ${numberFormat(cost)} Essence. Level ${level}"><span class="upgrade-icon" aria-hidden="true">${u.icon}</span><span><span class="upgrade-name">${u.name}</span><span class="upgrade-desc">${u.desc} · ${effect}</span></span><span class="upgrade-cost">${numberFormat(cost)} ✦<span class="upgrade-level">Lv. ${level}</span></span></button>`;
 }).join('');
}
function render(){
 $('essence').textContent=numberFormat(state.essence);
 $('totalRun').textContent=`${numberFormat(state.runEarned)} earned this age`;
 $('clickRate').textContent=numberFormat(clickPower());
 $('eps').textContent=numberFormat(essencePerSecond());
 $('sparkCount').textContent=numberFormat(state.sparks);
 $('multiplier').textContent=`${multiplier().toFixed(2)}× essence power`;
 const built=state.levels.filter(level=>level>0).length;
 $('buildCount').textContent=`${built===25?'Transcendent':'Awakened'} · ${built} / 25`;
 $('shopCount').textContent=`${built} / 25 awakened`;
 $('sparkBadge').textContent=`${numberFormat(state.sparks)} ${state.sparks===1?'spark':'sparks'}`;
 const possible=Math.floor(state.runEarned/PRESTIGE_THRESHOLD);
 $('prestigeText').textContent=state.runEarned>=PRESTIGE_THRESHOLD?`Rebirth now for ${numberFormat(possible)} Divine ${possible===1?'Spark':'Sparks'}. Your permanent multiplier will become ${(multiplier()+possible*.05).toFixed(2)}×.`:`Earn ${numberFormat(PRESTIGE_THRESHOLD)} Essence this age to rebirth. Each spark permanently increases all Essence by 5%. Current age: ${numberFormat(state.runEarned)} / ${numberFormat(PRESTIGE_THRESHOLD)}.`;
 const prestige=$('prestigeBtn');prestige.disabled=possible<1;prestige.textContent=possible?`Rebirth · Gain ${numberFormat(possible)} ${possible===1?'Spark':'Sparks'}`:`Rebirth · Need ${numberFormat(PRESTIGE_THRESHOLD)} Essence`;
 $('soundBtn').textContent=`♫ Sound: ${state.sound?'On':'Off'}`;
 $('features').innerHTML=upgrades.map((u,i)=>state.levels[i]>0?`<g class="feature on" data-feature="${i}" opacity="${Math.min(1,.72+Math.log2(state.levels[i]+1)*.08)}">${u.visual}</g>`:'').join('');
 renderShop();
}
function addEssence(amount){if(!(amount>0)||!Number.isFinite(amount))return;state.essence+=amount;state.runEarned+=amount;state.totalEarned+=amount}
function clickTemple(event){
 const amount=clickPower();addEssence(amount);render();
 const rect=$('scenePanel')?.getBoundingClientRect()||$('templeClick').getBoundingClientRect();
 const el=document.createElement('span');el.className='float-text';el.textContent=`+${numberFormat(amount)} ✦`;
 const x=event?.clientX?event.clientX-rect.left:rect.width/2;const y=event?.clientY?event.clientY-rect.top:rect.height/2;
 el.style.left=`${Math.max(8,Math.min(rect.width-100,x))}px`;el.style.top=`${Math.max(54,y)}px`;$('templeClick').appendChild(el);setTimeout(()=>el.remove(),850);
 if(state.sound)playChime();
}
function buyUpgrade(index){
 const item=upgrades[index];if(!item)return;
 const cost=upgradeCost(index);if(state.essence<cost)return;
 state.essence-=cost;state.levels[index]++;render();playChime(true);saveGame();
 showToast(`${item.name} awakened!`);
}
function playChime(isUpgrade=false){
 if(!state.sound)return;
 try{
  audioContext??=new(window.AudioContext||window.webkitAudioContext)();
  if(audioContext.state==='suspended')audioContext.resume();
  const osc=audioContext.createOscillator(),gain=audioContext.createGain();
  osc.type='triangle';osc.frequency.value=isUpgrade?660:440;gain.gain.setValueAtTime(.035,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.12);osc.connect(gain);gain.connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+.13);
 }catch(error){console.warn('Audio is unavailable.',error)}
}
function rebirth(){
 const gained=Math.floor(state.runEarned/PRESTIGE_THRESHOLD);if(gained<1)return;
 if(!confirm(`Rebirth this age for ${gained} Divine ${gained===1?'Spark':'Sparks'}? Essence and all upgrades will reset; sparks are permanent.`))return;
 state.sparks+=gained;state.essence=0;state.runEarned=0;state.levels=upgrades.map(()=>0);state.lastSaved=Date.now();saveGame();render();$('shopList').scrollTop=0;showToast(`A new age dawns · +${gained} Divine ${gained===1?'Spark':'Sparks'}`);
}
function resetGame(){
 if(!confirm('Erase all progress, including Divine Sparks, and begin again?'))return;
 state=initialState();saveGame();render();$('shopList').scrollTop=0;showToast('The sanctuary returns to its first stone.');
}
$('templeClick').addEventListener('click',clickTemple);
$('shopList').addEventListener('click',event=>{const button=event.target.closest('[data-upgrade]');if(button)buyUpgrade(Number(button.dataset.upgrade))});
$('prestigeBtn').addEventListener('click',rebirth);
$('resetBtn').addEventListener('click',resetGame);
$('soundBtn').addEventListener('click',()=>{state.sound=!state.sound;if(state.sound)playChime(true);render();saveGame()});
window.addEventListener('beforeunload',saveGame);
document.addEventListener('visibilitychange',()=>{if(document.hidden)saveGame()});
loadGame();render();
if(state.offlineGain)showToast(`Welcome back · +${numberFormat(state.offlineGain)} Essence gathered while away`);
let lastTick=Date.now();
setInterval(()=>{
 const now=Date.now(),elapsed=Math.min(2,(now-lastTick)/1000);lastTick=now;
 const production=essencePerSecond()*elapsed;if(production>0)addEssence(production);
 render();
 if(now-saveTimer>10000){saveTimer=now;saveGame()}
},200);
</script>
</body>
</html>

